(function(){'use strict';
function status(){try{return window.SageNative?JSON.parse(window.SageNative.readingStatus()):{connected:false};}catch(e){return {connected:false};}}
function escape(s){return String(s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
window.SageSetup={status:status,open:function(openPanel,panel){var s=status(),body=s.connected?'<p>已导入'+(s.ownerLabel?' · '+escape(s.ownerLabel):'本机阅读数据')+'</p>':'<p>用你自己的微信读书 Skill，连接你的阅读。</p>';openPanel('阅读数据',body+'<button class="system-row" data-setup="share">把配置说明交给 Agent</button><button class="system-row" data-setup="copy">复制配置说明</button><button class="system-row" data-setup="import">导入阅读数据</button>'+(s.connected?'<button class="system-row" data-setup="clear">移除本机阅读数据</button>':'')+'<p class="setup-foot">先由你的 Agent 完成 Skill 配置，再选择它返回的 quite-sage-data.json。</p>');panel.querySelectorAll('[data-setup]').forEach(function(b){b.onclick=function(){var action=b.getAttribute('data-setup');if(!window.SageNative){var p=panel.querySelector('.setup-preview');if(!p){p=document.createElement('p');p.className='setup-preview';panel.appendChild(p);}p.textContent='请在设备上完成导入；配置说明见项目 docs/reading-data-format.md。';return;}if(action==='share')window.SageNative.shareSetup();else if(action==='copy')window.SageNative.copySetup();else if(action==='import')window.SageNative.importReading();else window.SageNative.clearReading();};});}};
}());
